{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "While early PA participation is known to be positively associated with adulthood PA, mental health, and cardiovascular health, the specific activity types that most optimally benefit health outcomes remain unclear.",
      "reason": "The introduction describes the current state of knowledge (that early PA is associated with later outcomes) and explicitly identifies an important uncertainty — which specific activity types best benefit health outcomes."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "To optimise public health, a better understanding of PA participation behaviours and their relationship with health outcomes is needed. ... Therefore, summarising the current state of knowledge of the longitudinal health and behavioural effects of specific LTPA types could help inform public health policy and direct future research. ... As such, understanding which types of LTPA participation in early life may best promote positive lifelong PA behaviours and outcomes would be beneficial.",
      "reason": "The manuscript explains the public health importance and rationale for conducting the review, stating how improved understanding would inform policy, research, and promotion of lifelong activity."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Previous systematic reviews have highlighted the influence of activity structure and type on psychosocial outcomes in children [22] and cardiovascular health in adults [23]. Another review identified a largely positive relationship between overall childhood sport participation and adulthood PA [24]. However, the longitudinal associations between participation in specific LTPA types during childhood and adolescence and adult health and PA behaviours remains unknown. Therefore, this systematic review aims to collate previous findings on the associations between participation in specific types of LTPA in childhood and adolescence, and PA behaviours and mental and cardiovascular health-related outcomes in adulthood.",
      "reason": "The authors cite prior systematic reviews and explicitly state that the specific longitudinal associations remain unknown, justifying the need for the current review and positioning it relative to existing reviews."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This review concerns associations between leisure-time physical activity types and later outcomes, not effects of an intervention; no intervention mechanism is proposed in the manuscript, so this item does not apply."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not evaluate a complex intervention or delivery context and does not present or discuss a logic model; therefore this conditional item is not applicable."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No retrieved text explicitly states the review objective(s) or research question(s). The provided chunks include methods, selection criteria, strengths/limitations, and protocol registration but do not contain an explicit Objectives statement or question-formulation framing."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_4",
      "quote": "Studies were eligible for inclusion if they met the following criteria: - (ii) observational study design on humans with at least two timepoints of data collection;",
      "reason": "The review is of observational cohort studies (not interventions), as evidenced by the selection criteria specifying an 'observational study design' and cohort requirements; therefore PICO-style planned comparisons for intervention effects do not apply."
    }
  ],
  "confidence": 75
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Studies were eligible for inclusion if they met the following criteria: - (i) Full-text original peer-reviewed journal article published in English; - (ii) observational study design on humans with at least two timepoints of data collection; - (iii) cohort from the general population, - (iv) measurement of at least one specific type of LTPA (e.g., tennis, walking, strength-training), or grouping of specific types of LTPA with similar attributes (e.g., team sports, ball sports), in childhood or adolescence (aged 5-18 years); - (v) quantitative assessment of at least one mental health outcome (e.g., depression or anxiety symptoms/ diagnosis), cardiovascular health outcome (e.g., BMI, waist circumference, cholesterol, cardiovascular events/disease), or PA outcome in adulthood (aged 18 + years).",
      "reason": "The chunk lists detailed study characteristics used to determine eligibility: publication type/language, study design (observational, at least two timepoints), population (general population cohort, ages 5-18 for exposures, adulthood 18+ for outcomes), types of exposures (specific LTPA types or grouped types), and eligible outcomes."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Studies were eligible for inclusion if they met the following criteria: - (i) Full-text original peer-reviewed journal article published in English; ... No date restrictions were imposed on the search.",
      "reason": "The chunk explicitly states report characteristics: inclusion limited to full-text peer-reviewed journal articles published in English and also states that no date restrictions were applied."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": "text_12",
      "quote": "Reports excluded (n = 93): \n\u2022 No analysis of specific types of PA as exposure (n = 49)\n\u2022 Single timepoint (n = 15)\n\u2022 Not a peer-reviewed journal article (n = 18)\n\u2022 Wrong outcomes (n = 5)\n\u2022 Outside age range (n = 3)\n\u2022 Specialised population (n = 1)\n\u2022 Could not locate full text (n = 2)",
      "reason": "Although reasons for exclusion at full-text are listed, there is no explicit distinction provided in the evidence between excluding studies because outcomes were not measured versus excluding because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": "text_11",
      "quote": "Data from the included studies were collated by narrative synthesis due to the methodological and analytical differences present between studies.",
      "reason": "The evidence states that a narrative synthesis was used but does not specify the groups used in each synthesis or link those groups to the comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": "callout_0",
      "quote": "Studies were eligible for inclusion in the review if they were peer-reviewed and published in English; therefore, relevant grey literature and non-English studies may have been excluded.",
      "reason": "The manuscript acknowledges the exclusion of non-English and grey literature but does not provide an explicit rationale explaining why these notable restrictions on eligibility were imposed."
    }
  ],
  "confidence": 80
}

